#!/usr/bin/env bash
set -Eeuo pipefail
cd /opt/verirag/frontend
# Must be configured before deployment: /verirag/production/backend-url
# Example: http://internal-verirag-backend-<id>.ap-south-1.elb.amazonaws.com
url="$(aws ssm get-parameter --name '/verirag/production/backend-url' --region ap-south-1 --query 'Parameter.Value' --output text)"
[[ "$url" =~ ^https?://[^[:space:]]+$ ]] || { echo 'Invalid backend URL from SSM' >&2; exit 1; }
grep -Eq '^IMAGE_TAG=[a-f0-9]{40}$' release.env
# Validate no extra lines in release.env; generated by CI, never sourced as shell code.
[[ "$(wc -l < release.env)" -eq 1 ]] || { echo 'Unexpected release.env format' >&2; exit 1; }
printf 'BACKEND_URL=%s\n' "$url" >> release.env
chmod 600 release.env
printf 'Frontend runtime backend URL configured from SSM\n'

